async () => {
 const c=await connecta.call("billing.find_customer",{query:"Northwind Traders"});
 if(c.format!=="json") return {customer:c};
 const d=c.data;
 const candidates=Array.isArray(d)?d:(d?.customers||d?.results||[d]);
 const matches=candidates.filter(x=>JSON.stringify(x).toLowerCase().includes("northwind"));
 if(matches.length!==1) return {customerResults:c};
 const customer=matches[0], id=customer.id||customer.customerId;
 const inv=await connecta.call("billing.list_invoices",{customerId:id});
 return {customer, invoices:inv};
}

